async function readPublicCandlesForReal(symbol:string,interval:string,source:Source='live',strict=false):Promise<Candle[]>{
 if(source==='demo')return demoBars(symbol,interval).filter(x=>x.t+ms(interval)<=Date.now());
 try{const rows=await readFuturesRadar(symbol+'USDT',interval,500);return rows.filter(x=>Array.isArray(x)&&Number(x[0])+ms(interval)<=Date.now()).map(x=>({t:Number(x[0]),o:+x[1],h:+x[2],l:+x[3],c:+x[4],v:+x[5]})).filter(x=>[x.t,x.o,x.h,x.l,x.c,x.v].every(Number.isFinite))}catch(error){if(strict)throw Error(`${symbol} ${interval}: ${friendlyBrowserBinanceError(error)}`);return[]}
}
async function readHistoricalDaily(symbol:string,source:Source='live'):Promise<Candle[]>{
 const interval='1d',day=ms(interval),pageSize=500,maxPages=2;
 if(source==='demo')return demoBars(symbol,interval,Math.min(pageSize*maxPages,3000)).filter(x=>x.t+day<=Date.now());
 const output:Candle[]=[];let cursor=0;
 for(let page=0;page<maxPages;page++){
  try{
   const query=new URLSearchParams({symbol:`${symbol}USDT`,interval,limit:String(pageSize),startTime:String(cursor)});
   let response=await fetch(`/api/market?${query.toString()}`,{cache:'force-cache'}),payload:any=null;
   try{payload=await response.json()}catch{payload=null}
   let rows:any[]=Array.isArray(payload)?payload:Array.isArray(payload?.data)?payload.data:[];
   if(!response.ok||!rows.length){const direct=await fetch(`https://data-api.binance.vision/api/v3/klines?symbol=${symbol}USDT&interval=${interval}&limit=1000&startTime=${cursor}`,{signal:AbortSignal.timeout(15000)});if(!direct.ok)break;const raw=await direct.json();rows=Array.isArray(raw)?raw:[]}
   const batch=rows.filter(x=>Array.isArray(x)&&Number(x[0])+day<=Date.now()).map(x=>({t:Number(x[0]),o:Number(x[1]),h:Number(x[2]),l:Number(x[3]),c:Number(x[4]),v:Number(x[5])})).filter(x=>[x.t,x.o,x.h,x.l,x.c,x.v].every(Number.isFinite));
   if(!batch.length)break;const last=output.at(-1)?.t||0;for(const row of batch)if(row.t>last)output.push(row);const newest=batch.at(-1)!.t;if(newest<=cursor||newest+day>=Date.now()-day*2)break;cursor=newest+day;
  }catch{break}
 }
 return output;
}
